const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const configIO=require('../../../scripts/lib/configuration-file-io');
class SettingsError extends Error{constructor(message){super(message);this.name='SettingsError'}}
const fields={bos:[['bos-demand-query','connection'],['bos-demand-query','access_key'],['bos-demand-query','headers','X-Gateway-Upstream-BOS-MCP-TOKEN'],['bos-demand-query','cuser'],['bos-demand-query','cgroup'],['bos-code-update-log','connection'],['bos-code-update-log','token'],['bos-code-update-log','linkProject'],['bos-code-update-log','timeout']],knowledge:[['defaultProvider'],...['company','openai'].flatMap(p=>['type','model','dimensions',...(p==='company'?['baseUrl','method','appId','appKey']:['apiKey'])].map(k=>['providers',p,k]))]};
const secret=p=>/access_key|token|appKey|apiKey|connection|baseUrl/i.test(p.join('.'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const get=(o,p)=>p.reduce((v,k)=>v?.[k],o);
function createSettings(env=process.env){
 const plans=new Map();const cleanup=setInterval(()=>{for(const [k,v]of plans)if(v.expires<Date.now())plans.delete(k)},60000);cleanup.unref();
 function source(id){if(!fields[id])throw new SettingsError('未知配置域');const f=env[id==='bos'?'BOS_MCP_CONFIG':'KNOWLEDGE_RAG_CONFIG'];if(!f||!path.isAbsolute(f))throw new SettingsError('个人配置来源未绑定');const st=fs.lstatSync(f);if(!st.isFile()||st.isSymbolicLink())throw new SettingsError('仅支持普通本机配置文件');for(let d=path.dirname(f);;d=path.dirname(d)){if(fs.existsSync(path.join(d,'.git')))throw new SettingsError('个人配置位于 Git 工作区，禁止写入凭据');if(d===path.dirname(d))break}return f}
 function read(id){const file=source(id),bytes=fs.readFileSync(file),raw=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes),data=id==='knowledge'?configIO.parse(raw):JSON.parse(raw.replace(/^\uFEFF/,''));return {file,bytes,raw,data,revision:hash(bytes)}}
 function inspect(id){const s=read(id);return {id,revision:s.revision,scope:'共享个人配置',fields:fields[id].filter(p=>get(s.data,p)!==undefined).map(p=>({id:p.join('.'),label:p.at(-1),secret:secret(p),type:typeof get(s.data,p),value:secret(p)?undefined:get(s.data,p),configured:get(s.data,p)!==''&&get(s.data,p)!==null}))}}
 function plan(id,request){const s=read(id);if(request.revision!==s.revision)throw new SettingsError('配置已被外部修改，请重新读取后编辑');const data=structuredClone(s.data),changes=[];if(!request.changes||Array.isArray(request.changes))throw new SettingsError('修改格式错误');for(const [key,change]of Object.entries(request.changes)){const p=fields[id].find(p=>p.join('.')===key);if(!p||get(s.data,p)===undefined)throw new SettingsError('字段不在支持范围');let value=change.value;if(secret(p)){if(change.action==='keep')continue;if(!['replace','clear'].includes(change.action))throw new SettingsError('凭据操作无效');value=change.action==='clear'?'':value;if(typeof value!=='string'||(change.action==='replace'&&!value.trim()))throw new SettingsError('替换凭据不能为空')}else if(typeof value!==typeof get(s.data,p))throw new SettingsError('字段类型不匹配');if(typeof value==='string'&&value.length>8192)throw new SettingsError('字段过长');if(p.at(-1)==='dimensions'&&(!Number.isInteger(value)||value<1||value>65536))throw new SettingsError('向量维度应为 1–65536 整数');if(p.at(-1)==='timeout'&&(!Number.isFinite(Number(value))||Number(value)<=0))throw new SettingsError('超时必须大于零');if(key==='defaultProvider'&&!['company','openai'].includes(value))throw new SettingsError('未知提供方');if(get(s.data,p)===value)continue;let o=data;for(const k of p.slice(0,-1))o=o[k];o[p.at(-1)]=value;changes.push({field:key,action:secret(p)?change.action:'修改'})}const token=crypto.randomUUID();for(const [k,v]of plans)if(v.expires<Date.now())plans.delete(k);if(plans.size>20)throw new SettingsError('待保存预览过多，请稍后重试');plans.set(token,{id,file:fs.realpathSync(s.file),revision:s.revision,data,changes,expires:Date.now()+300000});return {planId:token,changes,scope:'所有引用同一个人配置文件的工程；无法枚举未登记工程',warning:id==='knowledge'?'提供方、模型或维度变更可能使已有索引不匹配；本次不删除或重建索引。':'查询与日志连接分别保存；本次不发起 BOS 请求。'}}
 function apply(token){const p=plans.get(token);plans.delete(token);if(!p||p.expires<Date.now())throw new SettingsError('预览已过期，请重新预览');const s=read(p.id);if(fs.realpathSync(s.file)!==p.file||s.revision!==p.revision)throw new SettingsError('配置已变更，已停止保存');if (!p.changes.length) return {status:'saved',revision:s.revision,message:'配置没有变化。'};const newline=s.raw.includes('\r\n')?'\r\n':'\n',indent=s.raw.match(/\n([ \t]+)"/)?.[1]||'  ';const encoded=p.id==='knowledge'?configIO.edit(s.raw,p.changes.map(({field})=>{const path=field.split('.');return {path,value:get(p.data,path)}})):(s.raw.startsWith('\uFEFF')?'\uFEFF':'')+JSON.stringify(p.data,null,indent).replace(/\n/g,newline)+(s.raw.endsWith('\n')?newline:'');const tmp=s.file+'.workbench-'+crypto.randomUUID()+'.tmp';try{fs.writeFileSync(tmp,encoded,{flag:'wx',mode:0o600});if(process.platform==='win32'){require('node:child_process').execFileSync('powershell.exe',['-NoProfile','-NonInteractive','-Command',"$ErrorActionPreference='Stop'; $p=[Console]::In.ReadToEnd() | ConvertFrom-Json; $acl=[System.IO.File]::GetAccessControl($p.source); [System.IO.File]::SetAccessControl($p.target,$acl)"],{input:JSON.stringify({source:s.file,target:tmp}),windowsHide:true,stdio:['pipe','pipe','pipe']})}else fs.chmodSync(tmp,fs.statSync(s.file).mode);if(hash(fs.readFileSync(s.file))!==s.revision)throw new SettingsError('写入前来源发生变化');fs.renameSync(tmp,s.file);const checked=read(p.id);if(JSON.stringify(checked.data)!==JSON.stringify(p.data))throw new SettingsError('读回未匹配，请保留现状检查');return {status:'saved',revision:checked.revision,message:'文件已保存并读回一致；远端认证未测试。'}}finally{if(fs.existsSync(tmp))fs.unlinkSync(tmp)}}
 return {inspect,plan,apply};
}
module.exports={createSettings};
